import csv
import io
import sys
import unittest
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from measurements import total
from export_csv import to_csv

class AggregateContract(unittest.TestCase):
    def test_final_rounding(self):
        self.assertEqual(total(["0.005", "0.005"]), "0.01")
    def test_cancellation(self):
        self.assertEqual(total(["9007199254740992", "1", "-9007199254740992"]), "1.00")
    def test_positive_tie(self):
        self.assertEqual(total(["1.005"]), "1.01")
    def test_negative_tie(self):
        self.assertEqual(total(["-1.005"]), "-1.01")
    def test_empty(self):
        self.assertEqual(total([]), "0.00")
    def test_zero(self):
        self.assertEqual(total(["-0.000001", "0.000001"]), "0.00")
    def test_thousand_small_values(self):
        self.assertEqual(total(["0.000006"] * 1000), "0.01")
    def test_upper_supported_magnitude(self):
        self.assertEqual(total(["999999999999999999.999999"] * 1000), "1000000000000000000000.00")

class CsvContract(unittest.TestCase):
    def test_special_fields(self):
        rows = [("1.2", "a,b"), ("3", 'say "yes"'), ("4", "two\nlines")]
        self.assertEqual(list(csv.reader(io.StringIO(to_csv(rows)))), [["value", "label"]] + [list(row) for row in rows])
    def test_empty(self):
        self.assertEqual(list(csv.reader(io.StringIO(to_csv([])))), [["value", "label"]])

if __name__ == "__main__":
    unittest.main()

